    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    logic d1, q1, d2, q2, d3, q3;

    // D flip-flops with synchronous reset (initialized to zero)
    always_ff @(posedge clk) begin
        q1 <= d1;
        q2 <= d2;
        q3 <= d3;
    end

    // Combinational logic for the D inputs
    // The specification states that the D flip-flops are initially reset to zero.
    // Since the reset state is zero and no explicit reset port is provided,
    // the initial values are implicitly zero at simulation start.
    // The D inputs are driven by the gates as described.
    assign d1 = x ^ q1;          // XOR gate: x XOR q1
    assign d2 = x & ~q2;         // AND gate: x AND (complemented q2)
