    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding: 0=walking_left, 1=walking_right, 2=falling, 3=digging
    parameter WALK_LEFT   = 2'b00;
    parameter WALK_RIGHT  = 2'b01;
    parameter FALLING     = 2'b10;
    parameter DIGGING     = 2'b11;

