module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD digits
);

    // Internal registers for the 4 BCD digits (ones, tens, hundreds, thousands)
    logic [3:0] ones;
    logic [3:0] tens;
    logic [3:0] hundreds;
    logic [3:0] thousands;

    // ena outputs: enable for the next higher digit
    // ena[0] -> tens, ena[1] -> hundreds, ena[2] -> thousands
    assign ena = {tens[3], hundreds[3], thousands[3]}; // MSB of each digit indicates overflow to next digit

    // BCD adder / increment logic for ones digit
    always_ff @(posedge clk) begin
        if (reset) begin
            ones <= 4'b0;
        end else begin
            // Increment ones; if it reaches 10 (1010), wrap to 0 and generate carry
            if (ones == 4'd9)
                ones <= 4'b0;
            else
                ones <= ones + 1'b1;
        end
    end

    // Tens digit: increment when ones overflows (ones wrapped from 9 to 0)
    always_ff @(posedge clk) begin
        if (reset) begin
            tens <= 4'b0;
        end else begin
            if (ones == 4'd9)
                if (tens == 4'd9)
                    tens <= 4'b0;
                else
                    tens <= tens + 1'b1;
            else
                tens <= tens; // no change
        end
    end

    // Hundreds digit: increment when tens overflows
    always_ff @(posedge clk) begin
        if (reset) begin
            hundreds <= 4'b0;
        end else begin
            if (tens == 4'd9)
                if (hundreds == 4'd9)
                    hundreds <= 4'b0;
                else
                    hundreds <= hundreds + 1'b1;
            else
                hundreds <= hundreds;
        end
    end

    // Thousands digit: increment when hundreds overflows
    always_ff @(posedge clk) begin
        if (reset) begin
            thousands <= 4'b0;
        end else begin
            if (hundreds == 4'd9)
                if (thousands == 4'd9)
                    thousands <= 4'b0;
                else
                    thousands <= thousands + 1'b1;
            else
                thousands <= thousands;
        end
    end

    // Concatenate the four digits to form the 16-bit output q
    assign q = {thousands, hundreds, tens, ones};

endmodule

