module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    reg [1:0] state;
    reg [1:0] byte_count;
    reg [23:0] shift_reg;

    always @(posedge clk) begin
        if (reset) begin
            state       <= 2'b00;
            byte_count  <= 2'b00;
            shift_reg   <= 24'b0;
            out_bytes   <= 24'b0;
            done        <= 1'b0;
        end else begin
            done <= 1'b0;

            case (state)
                2'b00: begin
                    if (in[3]) begin
                        state       <= 2'b01;
                        byte_count  <= 2'b01;
                        shift_reg   <= {in, 16'b0};
                    end else begin
                        state       <= 2'b00;
                    end
                end
                2'b01: begin
                    if (byte_count == 2'b10) begin
                        shift_reg <= {shift_reg[15:0], in};
                        out_bytes <= shift_reg;
                        done      <= 1'b1;
                        state     <= 2'b00;
                    end else begin
                        shift_reg <= {shift_reg[15:0], in};
                        byte_count <= byte_count + 2'b01;
                    end
                end
            endcase
        end
    end

endmodule

