module TopModule (
    input  logic [3:0] x,
    output logic       f
);

    // Internal signals for each minterm/maxterm
    logic x0, x1, x2, x3; // x[0], x[1], x[2], x[3] corresponding to x[3:0] (x[3] is MSB)

    // Assign internal signals based on input vector x[3:0]
    // x[3] -> x3, x[2] -> x2, x[1] -> x1, x[0] -> x0
    assign x3 = x[3];
    assign x2 = x[2];
    assign x1 = x[1];
    assign x0 = x[0];

    // Combinational assignment for f based on the K-map
    // K-map layout:
    //        x1 x2
    // x3 x4  00 01 11 10
    // 00   d  0  d  d
    // 01   0  d  1  0
    // 11   1  1  d  d
    // 10   1  1  0  d
    //
    // Variable mapping:
    // x3 -> row most significant (x[3])
    // x2 -> row least significant (x[2])  (Note: usually x3 is MSB, but K-map rows are x3x4. Here x[3:0] means x3,x2,x1,x0)
    // x1 -> column most significant (x[1])
    // x0 -> column least significant (x[0])
    //
    // Let's remap to standard K-map variables for grouping:
    // Let A = x3 (row MSb)
    // Let B = x2 (row LSb)
    // Let C = x1 (col MSb)
    // Let D = x0 (col LSb)
    //
    // K-map:
    // AB\CD 00 01 11 10
    // 00    d  0  d  d
    // 01    0  d  1  0
    // 11    1  1  d  d
    // 10    1  1  0  d

    // Deriving SOP expression from K-map groups:
    // Group 1: m(5,13,15,?) -> Let's list minterms where f=1 explicitly if possible, or use zeros/don't-cares.
    // Minterms for f=1: m(5, m(13,15), m(6,7,14,15?), m(12,13,14,15?))
    // Let's trace the table rows/cols.
    // Row 00 (AB=00): f=0 for CD=01 (m1), d for others.
    // Row 01 (AB=01): f=0 for CD=00 (m4), f=1 for CD=11 (m7), f=0 for CD=10 (m6). d for CD=01 (m5).
    // Row 11 (AB=11): f=1 for CD=00 (m12), f=1 for CD=01 (m13). d for CD=11 (m15), d for CD=10 (m14).
    // Row 10 (AB=10): f=1 for CD=00 (m8), f=1 for CD=01 (m9). f=0 for CD=11 (m11). d for CD=10 (m10).

    // Let's find prime implicants.
    // f = 1 for:
    // m7 (01 11) -> A'B CD
    // m13 (11 01) -> A B' CD
    // m12 (11 00) -> A B' C'D'
    // m9 (10 01) -> A B C'D
    // m8 (10 00) -> A B C'D'

    // Let's look at the K-map again carefully.
    // AB\CD 00 01 11 10
    // 00   d  0  d  d
    // 01   0  d  1  0
    // 11   1  1  d  d
    // 10   1  1  0  d

    // Grouping:
    // Group A: m(12,13) -> A B' D'? No, CD=00 and CD=01. So A B' (D doesn't matter). A B' (C'D' + C'D) = A B' C'.
    // Group B: m(8,9) -> A B C'D' + A B C'D = A B C'.
    // Group C: m(13,15) -> A B' D? CD=01 and CD=11. So A B' C? No, AB=11, CD=01,11. So A B D (C doesn't matter). A B (C'D + CD) = A B D.
    // Group D: m(5,7) -> AB=01, CD=11 and CD=01? No, row 01 has m7 (11) and m5 (01 is d). So m7 is 1. m5 is d.
    // Group E: m(6,14) -> Row 01 CD=10 (m6) is 0. Row 10 CD=10 (m10) is d. Row 11 CD=10 (m14) is d. Row 00 CD=10 is d. Not a clean group for 1s.
    // Group F: m(9,11?) -> m9 is 1, m11 is 0.
    // Group G: m(14,15) -> d,d. Can be used to extend groups.

    // Let's re-evaluate the K-map cells:
    // Row 00 (x3'x2'): CD=00 (d), CD=01 (0), CD=11 (d), CD=10 (d)
    // Row 01 (x3'x2): CD=00 (0), CD=01 (d), CD=11 (1), CD=10 (0)
    // Row 11 (x3x2): CD=00 (1), CD=01 (1), CD=11 (d), CD=10 (d)
    // Row 10 (x3x2'): CD=00 (1), CD=01 (1), CD=11 (0), CD=10 (d)

    // Variables: x3, x2, x1, x0.
    // Row select: x3, x2. (x3 is MSB of row select, x2 LSB)
    // Col select: x1, x0. (x1 is MSB of col, x0 LSB)

    // Let's list the function f(x3,x2,x1,x0):
    // f=1 for:
    // x3=0, x2=1, x1=1, x0=1 -> m7 (01 11) -> 1
    // f=1 for:
    // x3=1, x2=1, x1=0, x0=0 -> m12 (11 00) -> 1
    // f=1 for:
    // x3=1, x2=1, x1=0, x0=1 -> m13 (11 01) -> 1
    // f=1 for:
    // x3=1, x2=0, x1=0, x0=0 -> m8 (10 00) -> 1
    // f=1 for:
    // x3=1, x2=0, x1=0, x0=1 -> m9 (10 01) -> 1

    // Let's check the 0s and Ds.
    // f=0 for:
    // x3=0, x2=0, x1=0, x0=1 -> m1 (00 01) -> 0
    // f=0 for:
    // x3=0, x2=1, x1=0, x0=0 -> m4 (01 00) -> 0
    // f=0 for:
    // x3=0, x2=1, x1=1, x0=0 -> m6 (01 10) -> 0
    // f=0 for:
    // x3=1, x2=1, x1=1, x0=1 -> m15 (11 11) -> d
    // f=0 for:
    // x3=1, x2=1, x1=1, x0=0 -> m14 (11 10) -> d
    // f=0 for:
    // x3=1, x2=0, x1=1, x0=1 -> m11 (10 11) -> 0
    // f=0 for:
    // x3=0, x2=0, x1=0, x0=0 -> m0 (00 00) -> d
    // f=0 for:
    // x3=0, x2=0, x1=1, x0=0 -> m2 (00 10) -> d
    // f=0 for:
    // x3=0, x2=0, x1=1, x0=1 -> m3 (00 11) -> d

    // So explicit 1s: m7, m12, m13, m8, m9.
    // Explicit 0s: m1, m4, m6, m11.
    // Don't cares: m0, m2, m3, m14, m15.

    // Let's find SOP.
    // m8: x3 x2' x1' x0' -> x3 & ~x2 & ~x1 & ~x0
    // m9: x3 x2' x1' x1 -> x3 & ~x2 & ~x1 & x0
    // Combine m8 and m9: x3 & ~x2 & ~x1 (x0 doesn't matter) -> Term1: x3 ~x2 ~x1
    // m12: x3 x2 x1' x0' -> x3 & x2 & ~x1 & ~x0
    // m13: x3 x2 x1' x0 -> x3 & x2 & ~x1 & x0
    // Combine m12 and m13: x3 & x2 & ~x1 (x0 doesn't matter) -> Term2: x3 x2 ~x1
    // m7: x3' x2 x1 x0 -> ~x3 & x2 & x1 & x0

    // So f = x3 ~x2 ~x1 + x3 x2 ~x1 + ~x3 x2 x1 x0
    // Check if this covers all 1s and no 0s.
    // Term1 (x3 ~x2 ~x1): covers m8 (1000), m9 (1001). Correct.
    // Term2 (x3 x2 ~x1): covers m12 (1100), m13 (1101). Correct.
    // Term3 (~x3 x2 x1 x0): covers m7 (0111). Correct.
    // Does it cover any 0?
    // Term1: x3=1,x2=0,x1=0. 0s have x3=0 or x2=1 or x1=1. Safe.
    // Term2: x3=1,x2=1,x1=0. 0s have x3=0 or x2=0 or x1=1. Safe.
    // Term3: x3=0,x2=1,x1=1. 0s have x3=1 or x2=0 or x1=0. Safe.
    // What about don't cares? They can be 0 or 1. The expression implies specific values for don't cares.
    // m14 (1110): x3=1,x2=1,x1=1. Term2 has ~x1, so 0. Term3 has x1=1 but x3=0, so 0. Result 0. (Don't care, can be 0).
    // m15 (1111): x3=1,x2=1,x1=1. Same, 0.
    // m0 (0000): x3=0. Term3 has ~x3 but x2=0, so 0.
    // m2 (0010): x3=0,x2=0. 0.
    // m3 (0011): x3=0,x2=0. 0.

    // Is there a simpler expression?
    // f = x3 (~x2 ~x1 + x2 ~x1) + ~x3 x2 x1 x0
    // f = x3 ~x1 (~x2 + x2) + ~x3 x2 x1 x0
    // f = x3 ~x1 + ~x3 x2 x1 x0
    // Let's verify this simplified expression!
    // f = x3 & ~x1 | ~x3 & x2 & x1 & x0
    // Check m8 (1000): x3=1, x1=0 -> 1. OK.
    // Check m9 (1001): x3=1, x1=0 -> 1. OK.
    // Check m12 (1100): x3=1, x1=0 -> 1. OK.
    // Check m13 (1101): x3=1, x1=0 -> 1. OK.
    // Check m7 (0111): x3=0, x2=1, x1=1, x0=1 -> 1. OK.
    // Check m1 (0001): x3=0, x1=1 -> first term 0. second term: ~x3=1, x2=0 -> 0. Result 0. OK (m1 is 0).
    // Check m4 (0100): x3=0, x1=0 -> first term 0. second term: x2=1, but x1=0 -> 0. Result 0. OK (m4 is 0).
    // Check m6 (0110): x3=0, x1=1 -> first term 0. second term: x1=1, x0=0 -> 0. Result 0. OK (m6 is 0).
    // Check m11 (1011): x3=1 -> first term ~x1. x1=1 -> 0. Result 0. OK (m11 is 0).
    // Check m14 (1110): x3=1 -> ~x1. x1=1 -> 0. Result 0. (Don't care, but 0 is fine).
    // Check m15 (1111): x3=1 -> ~x1. x1=1 -> 0. Result 0. (Don't care).
    // Check m0 (0000): x3=0 -> second term. x2=0 -> 0. Result 0. (Don't care).
    // Check m2 (0010): x3=0 -> second term. x2=0 -> 0. Result 0. (Don't care).
    // Check m3 (0011): x3=0 -> second term. x2=0 -> 0. Result 0. (Don't care).

    // The expression f = (x3 & ~x1) | (~x3 & x2 & x1 & x0) is correct and minimal.
    // Wait, let's double check the K-map grouping to ensure no mistakes in variable names.
    // x[3:0] -> x3, x2, x1, x0.
    // K-map rows: x3 x2. Cols: x1 x0.
    // f = x3 ~x1 + ~x3 x2 x1 x0
    // This is a valid synthesizable expression.

    assign f = (x3 & ~x1) | (~x3 & x2 & x1 & x0);

endmodule

