module TopModule(
    input d,
    input done_counting,
    input ack,
    input [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot encoded state bits
    wire S = state[0];
    wire S1 = state[1];
    wire S11 = state[2];
    wire S110 = state[3];
    wire B0 = state[4];
    wire B1 = state[5];
    wire B2 = state[6];
    wire B3 = state[7];
    wire Count = state[8];
    wire Wait = state[9];

    // Next-state logic (one-hot)
    wire next_S = (!d & S) | (d & S110 & !d); // S from S (d=0) and S110 (d=0)
    wire next_S1 = (d & S) | (d & S1 & !d); // S1 from S (d=1) and S1 (d=0 -> wait, spec says S1 --d=0--> S, so next_S1 from S (d=1) only? Let's re-read spec carefully.)

    // Correct next-state derivation based on spec table:
    // S --d=0--> S, --d=1--> S1
    // S1 --d=0--> S, --d=1--> S11
    // S11 --d=0--> S110, --d=1--> S11
    // S110 --d=0--> S, --d=1--> B0
    // B0-->B1-->B2-->B3-->Count-->Wait-->S

    // Let's re-derive next state signals directly from state bits and inputs.
    // Since it's one-hot, only one state bit is 1 at a time.

    // next_S: Asserted when next state is S.
    // Next state is S if:
    // Current S and d=0, OR
    // Current S110 and d=0, OR
    // Current Wait and ack=1, OR
    // Current Count and done_counting=1? No, Count --done_counting=0--> Count, --done_counting=1--> Wait. So next state is NOT S from Count.
    // Current B0, B1, B2, B3 always go to next cycle, so NOT S from them unless they are B3 and... wait B3 goes to Count.
    // So next_S = (!d & S) | (!d & S110) | (ack & Wait).

    // next_S1: Asserted when next state is S1.
    // Next state is S1 if:
    // Current S and d=1.
    // So next_S1 = (d & S).

    // next_S11: Asserted when next state is S11.
    // Next state is S11 if:
    // Current S1 and d=1.
    // So next_S11 = (d & S1).

    // next_S110: Asserted when next state is S110.
    // Next state is S110 if:
    // Current S11 and d=0.
    // So next_S110 = (!d & S11).

    // next_B0: Asserted when next state is B0.
    // Next state is B0 if:
    // Current S110 and d=1.
    // So next_B0 = (d & S110).

    // next_B1: Asserted when next state is B1.
    // Next state is B1 if:
    // Current B0 (always go to next cycle).
    // So next_B1 = B0.

    // next_B2: Asserted when next state is B2.
    // Next state is B2 if:
    // Current B1.
    // So next_B2 = B1.

    // next_B3: Asserted when next state is B3.
    // Next state is B3 if:
    // Current B2.
    // So next_B3 = B2.

    // next_Count: Asserted when next state is Count.
    // Next state is Count if:
    // Current B3.
    // So next_Count = B3.

    // next_Wait: Asserted when next state is Wait.
    // Next state is Wait if:
    // Current Count and done_counting=1.
    // So next_Wait = (done_counting & Count).

    // Assign next-state signals
    assign next_S = (!d & S) | (!d & S110) | (ack & Wait);
    assign next_S1 = (d & S);
    assign next_S11 = (d & S1);
    assign next_S110 = (!d & S11);
    assign next_B0 = (d & S110);
    assign next_B1 = B0;
    assign next_B2 = B1;
    assign next_B3 = B2;
    assign next_Count = B3;
    assign next_Wait = (done_counting & Count);

    // Output logic (Moore machine, outputs depend only on current state)
    // shift_ena: Asserted in B0, B1, B2, B3
    assign shift_ena = B0 | B1 | B2 | B3;

    // counting: Asserted in Count state
    assign counting = Count;

    // done: Asserted in Wait state
    assign done = Wait;

    // Next-state output signals as requested
    // B3_next: Assert when next-state is B3
    assign B3_next = next_B3;
    // S_next: Assert when next-state is S
    assign S_next = next_S;
    // S1_next: Assert when next-state is S1
    assign S1_next = next_S1;
    // Count_next: Assert when next-state is Count
    assign Count_next = next_Count;
    // Wait_next: Assert when next-state is Wait
    assign Wait_next = next_Wait;

endmodule

