module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A = 3'b000,
        STATE_B = 3'b001,
        STATE_C = 3'b010,
        STATE_D = 3'b011,
        STATE_E = 3'b100,
        STATE_E1 = 3'b101,
        STATE_E2 = 3'b110,
        STATE_F = 3'b111
    } state_t;

    state_t state, next_state;

    // Sequential logic: state update on positive edge of clk
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= STATE_A;
        else
            state <= next_state;
    end

    // Combinational logic: next state and output generation
    always_comb begin
        // Default assignments: stay in current state, outputs hold
        next_state = state;
        f          = 1'b0;
        g          = 1'b0;

        case (state)
            STATE_A: begin
                // As long as reset is asserted (handled in seq), stay in A
                // When reset de-asserted, after next clock edge go to B
                // f is set to 1 for one cycle in STATE_B
                next_state = STATE_B;
            end

            STATE_B: begin
                // f is set to 1 for one clock cycle
                f = 1'b1;
                // After this cycle, monitor x
                if (x)
                    next_state = STATE_C;
                else
                    next_state = STATE_B; // stay if x not 1
            end

            STATE_C: begin
                // Monitor second '0' of sequence 1,0,1
                if (!x)
                    next_state = STATE_D;
                else
                    next_state = STATE_B; // reset if x not 0
            end

            STATE_D: begin
                // Monitor third '1' of sequence 1,0,1
                if (x) begin
                    // x is 1 -> sequence detected, set g = 1 next cycle
                    next_state = STATE_E;
                end else begin
                    next_state = STATE_B; // reset if x not 1
                end
            end

            STATE_E: begin
                // g is currently 1 (set on entry)
                // Monitor y within at most two clock cycles
                // If y becomes 1, stay in E (g stays 1)
                // If two cycles pass without y=1, go to STATE_F (g=0)
                if (y) begin
                    next_state = STATE_E; // y=1 detected, maintain g=1
                end else begin
                    // Need to count cycles without y=1
                    // Use internal states E1 and E2 for two-cycle wait
                    next_state = STATE_E1;
                end
            end

            STATE_E1: begin
                // First cycle without y=1
                if (y) begin
                    next_state = STATE_E; // y=1 detected, back to E
                end else begin
                    next_state = STATE_E2; // second cycle
                end
            end

            STATE_E2: begin
                // Second cycle without y=1
                if (y) begin
                    next_state = STATE_E; // y=1 detected, back to E
                end else begin
                    // y never became 1 within two cycles -> g=0 permanently
                    next_state = STATE_F;
                end
            end

            STATE_F: begin
                // g = 0 permanently until reset
                g = 1'b0;
                // Stay in F
                next_state = STATE_F;
            end

            default: next_state = STATE_A;
        endcase
    end

endmodule
